const root = $json || {};
const envelope = root.body && typeof root.body === 'object' ? root.body : root;
const data = envelope.data && typeof envelope.data === 'object' ? envelope.data : (root.data || envelope);
const key = data.key || envelope.key || root.key || {};
const msg = data.message || envelope.message || root.message || {};

function onlyDigits(value) {
  return String(value || '').split('@')[0].replace(/\D/g, '');
}

function firstPhone(candidates) {
  for (const candidate of candidates) {
    const digits = onlyDigits(candidate);
    if (digits.length >= 10) return digits;
  }
  return '';
}

const remoteJid = String(
  key.remoteJid || key.remoteJidAlt || data.remoteJid || data.from || envelope.from || root.from || ''
).trim();
const phone = firstPhone([
  key.remoteJid, key.remoteJidAlt, data.remoteJid, data.number, envelope.number,
  root.number, data.phone, envelope.phone, root.phone, data.sender, envelope.sender, root.sender
]);
const text = String(
  data.text || envelope.text || root.text || data.bodyText || envelope.bodyText ||
  msg.conversation || msg.extendedTextMessage?.text || msg.imageMessage?.caption ||
  msg.videoMessage?.caption || msg.documentMessage?.caption ||
  msg.buttonsResponseMessage?.selectedDisplayText || msg.listResponseMessage?.title ||
  msg.templateButtonReplyMessage?.selectedDisplayText || ''
).trim();
const messageId = String(
  key.id || data.messageId || data.id || envelope.message_id || root.message_id ||
  root.messageId || root.id || ''
).trim() || `${phone || 'unknown'}:${Date.now()}`;
const fromMe = Boolean(key.fromMe || data.fromMe || envelope.fromMe || root.fromMe);
const messageType = String(data.messageType || envelope.messageType || root.messageType || '').trim();
const instance = String(envelope.instance || data.instance || root.instance || $env.EVOLUTION_INSTANCE_NAME || '').trim();
const isGroup = remoteJid.includes('@g.us');
const canReply = Boolean(phone && !fromMe && !isGroup);
const isSupportedText = Boolean(text);
return [{ json: {
  phone,
  remote_jid: remoteJid,
  message_text: text,
  message_id: messageId,
  message_type: messageType,
  push_name: data.pushName || envelope.pushName || root.pushName || data.push_name || envelope.push_name || '',
  instance,
  from_me: fromMe,
  is_group: isGroup,
  can_reply: canReply,
  is_supported_text: isSupportedText,
  is_valid_user_message: Boolean(canReply && isSupportedText),
  current_date: new Date().toLocaleDateString('sv-SE', { timeZone: 'America/Sao_Paulo' }),
  current_datetime: new Date().toLocaleString('sv-SE', { timeZone: 'America/Sao_Paulo', hour12: false }).replace(' ', 'T'),
  raw: root
} }];

function cleanJsonContent(value) {
  if (value && typeof value === 'object') return value;
  const raw = String(value || '').trim();
  if (!raw) return '';
  const withoutFence = raw.replace(/^```(?:json)?\s*/i, '').replace(/```$/i, '').trim();
  const first = withoutFence.indexOf('{');
  const last = withoutFence.lastIndexOf('}');
  if (first >= 0 && last > first) return withoutFence.slice(first, last + 1);
  return withoutFence;
}
const content = $json.output ?? $json.text ?? $json.response ?? $json.choices?.[0]?.message?.content ?? '';
let parsed;
try {
  const cleaned = cleanJsonContent(content);
  parsed = typeof cleaned === 'object' ? cleaned : JSON.parse(cleaned);
} catch (error) {
  parsed = {
    intent: 'help',
    confidence: 0,
    needs_clarification: false,
    reply_text: 'Posso te ajudar com a Central de Acertos: quem te deve, o que você deve, rascunhos, aceite/recusa, pagamento e Pix mensal. Me manda do seu jeito. 😉'
  };
}
if (!parsed || typeof parsed !== 'object') parsed = { intent: 'help', reply_text: 'Me manda o que você quer ver na Central de Acertos.' };
const apiIntents = new Set(['shared_debt_summary','list_incoming_debts','list_outgoing_debts','list_draft_queues','send_draft_queue','accept_debt','reject_debt','contest_debt','mark_as_paid','confirm_received','generate_pix']);
parsed.should_call_api = apiIntents.has(String(parsed.intent || '')) && parsed.needs_clarification !== true;
if (parsed.needs_clarification === true && !parsed.clarifying_question) parsed.clarifying_question = 'Me dá mais um detalhe para eu não mexer errado na Central de Acertos?';
if (['greeting','help'].includes(String(parsed.intent || '')) && !parsed.reply_text) {
  parsed.reply_text = 'Oi! Aqui é seu concierge da Central de Acertos do AcerttaPay. Posso mostrar quem te deve, o que você deve, listar rascunhos, preparar envio, aceitar/recusar acertos, marcar pagamento e gerar Pix mensal. 🤝';
}
if (String(parsed.intent || '') === 'out_of_scope' && !parsed.reply_text) parsed.reply_text = 'Essa função ainda não entrou na Central de Acertos por WhatsApp. Por enquanto, cuido de pendências, rascunhos, pagamentos e Pix mensal.';
return [{ json: parsed }];

const parsed = $json || {};
const intent = String(parsed.intent || '').trim();
const phone = $('Normalize Evolution Payload').first().json.phone;
const source = {
  channel: 'whatsapp',
  instance: $('Normalize Evolution Payload').first().json.instance,
  message_id: $('Normalize Evolution Payload').first().json.message_id,
  raw_text: $('Normalize Evolution Payload').first().json.message_text
};
const query = parsed.query || {};
const target = parsed.target || {};
const action = parsed.action || {};
let endpoint = '/api/automation/v1/shared-debts/summary';
let body = { phone, source, query };
let idempotencySuffix = intent;
function cleanId(value) {
  return String(value || '0').replace(/[^0-9]/g, '') || '0';
}
if (intent === 'shared_debt_summary') {
  endpoint = '/api/automation/v1/shared-debts/summary';
} else if (intent === 'list_incoming_debts') {
  endpoint = '/api/automation/v1/shared-debts/requests';
  body.query = { ...query, direction: 'incoming' };
} else if (intent === 'list_outgoing_debts') {
  endpoint = '/api/automation/v1/shared-debts/requests';
  body.query = { ...query, direction: 'outgoing' };
} else if (intent === 'list_draft_queues') {
  endpoint = '/api/automation/v1/shared-debts/drafts';
} else if (intent === 'send_draft_queue') {
  const id = cleanId(target.queue_id || target.id);
  endpoint = `/api/automation/v1/shared-debts/drafts/${id}/prepare-send`;
  body.query = { ...query, person_hint: target.person_hint || query.person_hint || null };
  idempotencySuffix += ':' + id;
} else if (intent === 'accept_debt' || intent === 'reject_debt' || intent === 'contest_debt') {
  const id = cleanId(target.request_id || target.id);
  endpoint = `/api/automation/v1/shared-debts/requests/${id}/respond`;
  body.action = intent === 'accept_debt' ? 'accept' : intent === 'reject_debt' ? 'reject' : 'contest';
  body.note = action.note || null;
  body.query = { ...query, person_hint: target.person_hint || query.person_hint || null };
  idempotencySuffix += ':' + id;
} else if (intent === 'mark_as_paid') {
  const id = cleanId(target.request_id || target.id);
  endpoint = `/api/automation/v1/shared-debts/requests/${id}/mark-paid`;
  body.note = action.note || null;
  body.query = { ...query, person_hint: target.person_hint || query.person_hint || null };
  idempotencySuffix += ':' + id;
} else if (intent === 'confirm_received') {
  const id = cleanId(target.request_id || target.id);
  endpoint = `/api/automation/v1/shared-debts/requests/${id}/confirm-received`;
  body.note = action.note || null;
  body.query = { ...query, person_hint: target.person_hint || query.person_hint || null };
  idempotencySuffix += ':' + id;
} else if (intent === 'generate_pix') {
  const id = cleanId(target.settlement_id || target.id);
  endpoint = `/api/automation/v1/shared-debts/settlements/${id}/pix/prepare`;
  body.amount_cents = action.amount_cents || null;
  body.query = { ...query, person_hint: target.person_hint || query.person_hint || null };
  idempotencySuffix += ':' + id;
}
return [{ json: { intent, endpoint, body, idempotency_key: `whatsapp-shared-debt:${$('Normalize Evolution Payload').first().json.instance}:${$('Normalize Evolution Payload').first().json.message_id}:${idempotencySuffix}` } }];

const result = $json || {};
let text = result.whatsapp?.text || result.message || result.reply_text || '';
if (!text) text = 'Central de Acertos processada no AcerttaPay, mas a resposta veio tímida. Tenta de novo em instantes.';
return [{ json: { ...result, outbound_text: text } }];

const phone = $('Normalize Evolution Payload').first().json.phone;
const source = {
  channel: 'whatsapp',
  instance: $('Normalize Evolution Payload').first().json.instance,
  message_id: $('Normalize Evolution Payload').first().json.message_id,
  raw_text: $('Normalize Evolution Payload').first().json.message_text
};
return [{ json: {
  endpoint: '/api/automation/v1/shared-debts/conversations/reply',
  idempotency_key: `whatsapp-shared-debt-reply:${$('Normalize Evolution Payload').first().json.instance}:${$('Normalize Evolution Payload').first().json.message_id}`,
  body: { phone, source, reply: { raw_text: $('Normalize Evolution Payload').first().json.message_text } }
} }];
